<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/uji/tools/core.php';
const KF_VIEW='vw_ringkasan_transaksi_terpadu';
function kfInput():array{$v=base64_decode(trim(stream_get_contents(STDIN)),true);ksAssert($v!==false,'Input tidak valid');$s=json_decode($v,true,64,JSON_THROW_ON_ERROR);ksAssert(is_array($s),'Input bukan objek');return $s;}
function kfJson(string $p,array $v):void{$s=json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);ksAssert(file_put_contents($p,$s)===strlen($s),'Penulisan JSON gagal');}
function kfManifest(string $n='manifest-final.json'):array{return json_decode(file_get_contents(dirname(__DIR__).'/'.$n),true,512,JSON_THROW_ON_ERROR)['files'];}
function kfSource(array $s,string $stage='either'):array{$t=realpath($s['target']??'');ksAssert(is_string($t)&&basename($t)==='kalawa-service-f1-korporat-uji','Target tidak sesuai situs yang ditinjau');foreach(kfManifest() as $f){$p=$t.'/'.$f['path'];ksAssert(is_file($p)&&hash_file('sha256',$p)===$f['after'],'Source Cetak R05 berbeda: '.$f['path']);}require_once $t.'/app/database_m2.php';return [$t,require dirname($t,2).'/kalawa-korporat-uji-config.php',koneksiKalawaM2()];}
function kfAdmin(array $s,array $c,string $db=KS_TEST_SOURCE_DB):PDO{return ksTestPdo($c,$db,$s['admin_user'],$s['admin_password']);}
function kfFolder(string $d,string $t):void{$d=str_replace('\\','/',$d);$h=str_replace('\\','/',dirname($t));ksAssert(strcasecmp($d,$h)!==0&&stripos($d,rtrim($h,'/').'/')!==0,'Hasil wajib di luar htdocs');ksAssert(!file_exists($d)&&mkdir($d,0700,true),'Folder hasil sudah ada atau gagal dibuat');}
function kfPortable(string $s):string{return preg_replace('/\bDEFINER\s*=\s*`(?:``|[^`])*`@`(?:``|[^`])*`\s*/i','',$s,1);}
function kfNorm(string $s,string $db):string{return preg_replace('/\s+/',' ',trim(ksRewriteSql(kfPortable($s),$db,'KALAWA_SCHEMA')));}
function kfObjectList(PDO $p,string $db):array{$all=[];$q=$p->prepare('SELECT ROUTINE_NAME AS n,ROUTINE_TYPE AS t FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=? ORDER BY ROUTINE_TYPE,ROUTINE_NAME');$q->execute([$db]);$all=$q->fetchAll();foreach(['VIEW'=>['information_schema.VIEWS','TABLE_NAME','TABLE_SCHEMA'],'TRIGGER'=>['information_schema.TRIGGERS','TRIGGER_NAME','TRIGGER_SCHEMA']] as $t=>[$table,$col,$sc]){$q=$p->prepare("SELECT $col FROM $table WHERE $sc=? ORDER BY $col");$q->execute([$db]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $n)$all[]=['t'=>$t,'n'=>$n];}return $all;}
function kfObjects(PDO $p,string $db):array{$o=[];foreach(ksBaseTables($p,$db) as $n)$o['TABLE:'.$n]=hash('sha256',kfNorm(ksCreateDefinition($p,'TABLE',$n),$db));foreach(kfObjectList($p,$db) as $r)$o[$r['t'].':'.$r['n']]=hash('sha256',kfNorm(ksCreateDefinition($p,$r['t'],$r['n']),$db));ksort($o);return $o;}
function kfExport(PDO $p,string $db,string $path,bool $portable=false):array{$f=fopen($path,'x');ksAssert($f!==false,'Backup sudah ada atau gagal dibuat');$p->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$p->exec('SET TRANSACTION READ ONLY');$p->beginTransaction();try{ksWriteBackup($f,"-- Kalawa: backup konsisten, impor ke database baru.\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");$ts=ksBaseTables($p,$db);foreach($ts as $t)ksWriteBackup($f,'DROP TABLE IF EXISTS '.ksName($t).";\n".ksCreateDefinition($p,'TABLE',$t).";\n");foreach($ts as $t){$cs=array_column(array_filter(ksColumns($p,$t),fn($c)=>stripos($c['Extra'],'GENERATED')===false),'Field');$cols=implode(',',array_map('ksName',$cs));$q=$p->query('SELECT '.$cols.' FROM '.ksName($t));while($r=$q->fetch(PDO::FETCH_NUM))ksWriteBackup($f,'INSERT INTO '.ksName($t).' ('.$cols.') VALUES ('.implode(',',array_map(fn($v)=>$v===null?'NULL':$p->quote((string)$v),$r)).");\n");}foreach(kfObjectList($p,$db) as $r){$ddl=ksCreateDefinition($p,$r['t'],$r['n']);ksWriteBackup($f,"\nDELIMITER $$\n".($portable?kfPortable($ddl):$ddl)."$$\nDELIMITER ;\n");}ksWriteBackup($f,"SET FOREIGN_KEY_CHECKS=1;\n");ksAssert(fflush($f),'Backup belum tersimpan lengkap');$snap=['tables'=>ksDigests($p,$db),'objects'=>kfObjects($p,$db)];$p->commit();return $snap;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}finally{fclose($f);}}
function kfSqlStatements(string $file):Generator{$f=fopen($file,'r');ksAssert($f!==false,'SQL tidak bisa dibaca');$buf='';$del=';';$quote='';$block=false;try{while(($line=fgets($f))!==false){if($quote===''&&!$block&&trim($buf)===''&&preg_match('/^\s*DELIMITER\s+(\S+)\s*$/i',$line,$m)){$del=$m[1];continue;}for($i=0,$n=strlen($line);$i<$n;$i++){$c=$line[$i];$next=$line[$i+1]??'';if($block){if($c==='*'&&$next==='/'){$block=false;$i++;}continue;}if($quote!==''){$buf.=$c;if($c==='\\'&&$quote!=='`'&&$i+1<$n){$buf.=$line[++$i];continue;}if($c===$quote){if($next===$quote)$buf.=$line[++$i];else $quote='';}continue;}if($c==='/'&&$next==='*'){$block=true;$buf.=' ';$i++;continue;}if($c==='#'||($c==='-'&&$next==='-'&&ctype_space($line[$i+2]??' '))){$buf.="\n";break;}if(in_array($c,["'",'"','`'],true)){$quote=$c;$buf.=$c;continue;}if(substr($line,$i,strlen($del))===$del){$s=trim($buf);$buf='';$i+=strlen($del)-1;if($s!=='')yield $s;continue;}$buf.=$c;}}ksAssert($quote===''&&!$block&&trim($buf)==='','SQL terpotong/delimiter belum ditutup');}finally{fclose($f);}}
function kfImport(PDO $p,string $f,string $db):void{foreach(kfSqlStatements($f) as $s){ksAssert(!preg_match('/^\s*(USE|GRANT|REVOKE|CREATE\s+(?:DATABASE|USER)|DROP\s+(?:DATABASE|USER))\b/i',$s),'Dump memuat operasi di luar DB baru');$p->exec(ksRewriteSql($s,KS_TEST_SOURCE_DB,$db));}}
function kfViewExists(PDO $p):bool{return (int)ksOne($p,'SELECT COUNT(*) FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?',[KF_VIEW])===1;}
function kfViewChecks(PDO $p):array{ksAssert(kfViewExists($p),'View terpadu belum tersedia');$qs=[
'Satu baris per WO'=>'SELECT (SELECT COUNT(*) FROM vw_ringkasan_transaksi_terpadu)=(SELECT COUNT(*) FROM work_order)',
'Tidak ada duplikasi WO'=>'SELECT COUNT(*)=COUNT(DISTINCT no_work_order) FROM vw_ringkasan_transaksi_terpadu',
'Status korporat sesuai'=>"SELECT COUNT(*)=0 FROM vw_ringkasan_transaksi_terpadu v JOIN work_order_korporat wk ON wk.no_work_order=v.no_work_order LEFT JOIN detail_tagihan_korporat d ON d.no_work_order=v.no_work_order LEFT JOIN tagihan_korporat t ON t.id_tagihan=d.id_tagihan WHERE v.status_pekerjaan<>'DIBATALKAN' AND (NOT(v.status_pembayaran<=>COALESCE(t.status_pembayaran,'BELUM_DITAGIHKAN')) OR NOT(v.id_tagihan<=>d.id_tagihan))",
'Nilai korporat per WO tepat'=>"SELECT COUNT(*)=0 FROM vw_ringkasan_transaksi_terpadu v JOIN detail_tagihan_korporat d ON d.no_work_order=v.no_work_order JOIN tagihan_korporat t ON t.id_tagihan=d.id_tagihan WHERE NOT(v.nilai_wo<=>d.nilai_final) OR NOT(v.penerimaan_wo<=>CASE WHEN t.status_pembayaran='LUNAS' AND v.status_pekerjaan<>'DIBATALKAN' THEN d.nilai_final ELSE 0 END)",
'Nilai individual tepat'=>"SELECT COUNT(*)=0 FROM vw_ringkasan_transaksi_terpadu v JOIN pembayaran p ON p.no_work_order=v.no_work_order WHERE v.jenis_transaksi='INDIVIDUAL' AND (NOT(v.nilai_wo<=>p.total_bayar) OR NOT(v.status_pembayaran<=>CASE WHEN v.status_pekerjaan='DIBATALKAN' THEN 'TIDAK_DITAGIH' ELSE p.status_pembayaran END) OR NOT(v.penerimaan_wo<=>CASE WHEN p.status_pembayaran='LUNAS' AND v.status_pekerjaan<>'DIBATALKAN' THEN p.total_bayar ELSE 0 END))",
'WO batal tidak ditagih'=>"SELECT COUNT(*)=0 FROM vw_ringkasan_transaksi_terpadu WHERE status_pekerjaan='DIBATALKAN' AND (penerimaan_wo<>0 OR status_pembayaran<>'TIDAK_DITAGIH')"];
foreach($qs as $label=>$q)ksAssert((int)ksOne($p,$q)===1,$label);return array_keys($qs);}
function kfGrantApp(PDO $p,string $db=KS_TEST_SOURCE_DB,string $user=KS_TEST_SOURCE_USER):void{$s=preg_replace('/^--.*$/m','',file_get_contents(dirname(__DIR__).'/uji/tools/izin-template.sql'));$s=str_replace('`'.KS_TEST_SOURCE_DB.'`','`'.$db.'`',$s);$s=str_replace("'".KS_TEST_SOURCE_USER."'@'127.0.0.1'",$p->quote($user)."@'127.0.0.1'",$s);foreach(explode(';',$s) as $q){$q=trim($q);if($q==='')continue;ksAssert(str_starts_with($q,'GRANT ')&&!preg_match('/\b(ALL|TRIGGER|GRANT OPTION)\b/',$q),'Template izin ditolak');$p->exec($q);}}
function kfReplace(string $p,string $s):void{$tmp=$p.'.t4-'.bin2hex(random_bytes(4));ksAssert(file_put_contents($tmp,$s)===strlen($s),'Berkas sementara gagal');if(!@rename($tmp,$p)){@unlink($tmp);throw new RuntimeException('Penggantian berkas gagal; berkas lama dipertahankan');}}
function kfIdentitySame(array $a,array $b):bool{foreach(['db','hostname','port','server_id','versi'] as $k)if((string)($a[$k]??'')!==(string)($b[$k]??''))return false;return true;}
function kfMarker(string $t):string{return dirname($t,2).'/kalawa-final-t4-state.json';}
function kfFail(Throwable $e):never{fwrite(STDERR,'DIHENTIKAN: '.($e instanceof PDOException?'MariaDB kode '.(int)($e->errorInfo[1]??0):$e->getMessage()).PHP_EOL);exit(1);}
